+        background: var(--accent);
+        transition: transform 0.2s ease, background 0.2s ease;
+      }
+
+      .faq-toggle[aria-expanded="true"] .icon {
+        transform: rotate(45deg);
+        background: var(--accent-strong);
+      }
+
+      .details {
+        padding: 0 1.25rem 1.25rem;
+        color: var(--muted);
+      }
+
+      .details[hidden] {
+        display: none;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      .details p + p {
+        margin-top: 0.85rem;
+      }
+
