+    <main id="main">
+      <header class="hero">
+        <h1>Cat FAQ</h1>
+        <p class="lead">
+          Quick answers to common questions about cats, from naps and purrs to
+          why they act like they own the place.
+        </p>
+      </header>
+
+      <section class="faq" aria-label="Frequently asked questions">
+        <div class="example">
+          <button class="faq-toggle" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
+            <span class="question">Why do cats sleep so much?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="answer-1" role="region" aria-labelledby="question-1" hidden>
+            <p>
+              Cats are built for short bursts of energy, so they conserve fuel
