<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #121a2f;
        --panel-2: #18213a;
        --text: #edf2ff;
        --muted: #aeb9d6;
        --accent: #8bb3ff;
        --accent-strong: #c4d6ff;
        --border: #2d3a5f;
        --shadow: 0 16px 40px #00000066;
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font: 16px/1.6 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #243253 0, transparent 45%),
          linear-gradient(180deg, #0b1020 0%, #090d18 100%);
      }

      a,
      button {
        font: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--accent);
        color: #07101f;
        transform: translateY(-200%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        width: min(920px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 4.5rem 0 5rem;
      }

      .hero {
        margin-bottom: 2rem;
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2.2rem, 4vw, 4rem);
        line-height: 1.05;
        letter-spacing: -0.04em;
      }

      .lead {
        margin: 0;
        max-width: 65ch;
        color: var(--muted);
        font-size: 1.05rem;
      }

      .faq {
        display: grid;
        gap: 1rem;
      }

      .example {
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: linear-gradient(180deg, var(--panel) 0%, var(--panel-2) 100%);
        box-shadow: var(--shadow);
        overflow: clip;
      }

      .faq-toggle {
        width: 100%;
        padding: 1.2rem 1.25rem;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        border: 0;
        background: transparent;
        color: var(--text);
        text-align: left;
        cursor: pointer;
      }

      .faq-toggle:hover {
        background: #ffffff08;
      }

      .faq-toggle:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: -3px;
      }

      .question {
        font-size: 1.1rem;
        font-weight: 700;
      }

      .icon {
        flex: none;
        width: 2rem;
        height: 2rem;
        border-radius: 999px;
        display: grid;
        place-items: center;
        color: #07101f;
        background: var(--accent);
        transition: transform 0.2s ease, background 0.2s ease;
      }

      .faq-toggle[aria-expanded="true"] .icon {
        transform: rotate(45deg);
        background: var(--accent-strong);
      }

      .details {
        padding: 0 1.25rem 1.25rem;
        color: var(--muted);
      }

      .details[hidden] {
        display: none;
      }

      .details p {
        margin: 0;
      }

      .details p + p {
        margin-top: 0.85rem;
      }

      @media (forced-colors: active) {
        body,
        .example,
        .faq-toggle,
        .icon,
        .skip-link {
          forced-color-adjust: auto;
        }

        .example {
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .faq-toggle:focus-visible,
        .skip-link:focus {
          outline: 2px solid Highlight;
        }
      }

      @media (max-width: 560px) {
        main {
          width: min(100% - 1rem, 920px);
          padding-top: 3.5rem;
        }

        .faq-toggle {
          padding: 1rem;
        }

        .details {
          padding: 0 1rem 1rem;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <header class="hero">
        <h1>Cat FAQ</h1>
        <p class="lead">
          Quick answers to common questions about cats, from naps and purrs to
          why they act like they own the place.
        </p>
      </header>

      <section class="faq" aria-label="Frequently asked questions">
        <div class="example">
          <button class="faq-toggle" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
            <span class="question">Why do cats sleep so much?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="answer-1" role="region" aria-labelledby="question-1" hidden>
            <p>
              Cats are built for short bursts of energy, so they conserve fuel
              by napping a lot. Most adult cats sleep between 12 and 16 hours a
              day.
            </p>
          </div>
        </div>

        <div class="example">
          <button class="faq-toggle" type="button" aria-expanded="false" aria-controls="answer-2" id="question-2">
            <span class="question">Why do cats purr?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="answer-2" role="region" aria-labelledby="question-2" hidden>
            <p>
              Cats often purr when they feel relaxed, but they may also purr
              when they want comfort or are healing. It is a versatile little
              engine.
            </p>
          </div>
        </div>

        <div class="example">
          <button class="faq-toggle" type="button" aria-expanded="false" aria-controls="answer-3" id="question-3">
            <span class="question">Do cats need baths?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="answer-3" role="region" aria-labelledby="question-3" hidden>
            <p>
              Usually not. Healthy cats groom themselves well. A bath is mostly
              only needed if they get into something sticky, dirty, or unsafe.
            </p>
          </div>
        </div>

        <div class="example">
          <button class="faq-toggle" type="button" aria-expanded="false" aria-controls="answer-4" id="question-4">
            <span class="question">Why do cats knead blankets?</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="details" id="answer-4" role="region" aria-labelledby="question-4" hidden>
            <p>
              Kneading is a comforting behavior tied to kittenhood. Cats often
              do it when they feel safe, cozy, or ready to settle in.
            </p>
          </div>
        </div>
      </section>
    </main>

    <script>
      document.querySelectorAll('.faq-toggle').forEach((button) => {
        const panel = document.getElementById(button.getAttribute('aria-controls'));

        button.addEventListener('click', () => {
          const expanded = button.getAttribute('aria-expanded') === 'true';
          button.setAttribute('aria-expanded', String(!expanded));
          panel.hidden = expanded;
        });
      });
    </script>
  </body>
</html>
